unsigned int hex_byte(const char* s, int* ok)
{
    unsigned int v = 0;
    for (int i = 0; i < 2; ++i) {
        char c = s[i];
        v <<= 4;
        if (c >= '0' && c <= '9') {
            v |= static_cast<unsigned>(c - '0');
        } else if (c >= 'a' && c <= 'f') {
            v |= static_cast<unsigned>(c - 'a' + 10);
        } else if (c >= 'A' && c <= 'F') {
            v |= static_cast<unsigned>(c - 'A' + 10);
        } else {
            *ok = 0;
            return 0;
        }
    }
    return v;
}

unsigned int hex_nib(char c, int* ok)
{
    if (c >= '0' && c <= '9') {
        return static_cast<unsigned>(c - '0');
    }
    if (c >= 'a' && c <= 'f') {
        return static_cast<unsigned>(c - 'a' + 10);
    }
    if (c >= 'A' && c <= 'F') {
        return static_cast<unsigned>(c - 'A' + 10);
    }
    *ok = 0;
    return 0;
}

void split_grad_parts(const std::string& s, std::vector<std::string>& out)
{
    size_t depth = 0, start = 0;
    for (size_t i = 0; i <= s.size(); ++i) {
        char c = i < s.size() ? s[i] : ',';
        if (c == '(') {
            ++depth;
        } else if (c == ')') {
            if (depth > 0) {
                --depth;
            }
        } else if (c == ',' && depth == 0) {
            std::string part = s.substr(start, i - start);
            size_t b = part.find_first_not_of(" \t");
            size_t e = part.find_last_not_of(" \t");
            if (b != std::string::npos) {
                out.push_back(part.substr(b, e - b + 1));
            }
            start = i + 1;
        }
    }
}

int parse_gradient(const std::string& v, Gradient& out)
{
    size_t li = v.find("linear-gradient(");
    size_t ri = v.find("radial-gradient(");
    if (li == std::string::npos && ri == std::string::npos) {
        return 0;
    }
    bool lin = li != std::string::npos &&
               (ri == std::string::npos || li < ri);
    size_t start = lin ? li : ri;
    /* "linear-gradient(" / "radial-gradient(" are both 16 chars */
    size_t open = start + 16;
    size_t depth = 1;
    size_t end = std::string::npos;
    for (size_t i = open; i < v.size(); ++i) {
        if (v[i] == '(') {
            ++depth;
        } else if (v[i] == ')') {
            if (--depth == 0) {
                end = i;
                break;
            }
        }
    }
    if (end == std::string::npos) {
        return 0;
    }
    out = Gradient();
    out.type = lin ? 0 : 1;
    out.angle_deg = 180.0f; /* default: to bottom */
    out.rx = 0;
    out.ry = 0;
    out.cx = 0.5f;
    out.cy = 0.5f;
    std::vector<std::string> parts;
    split_grad_parts(v.substr(open, end - open), parts);
    if (parts.empty()) {
        return 0;
    }
    size_t first = 1;
    if (!lin) {
        /* radial first part: "[circle|ellipse] <size> at <pos>".
         * Sizes: "200px" (circle r), "110px 60px" (ellipse radii),
         * closest-side / closest-corner / farthest-side / farthest-corner
         * (resolved against the box at paint time via rx/ry markers below),
         * "circle"/"ellipse" alone (defaults). Positions: "72% -12%",
         * "100px 20px", single value (= horizontal, vertical centers), or
         * keywords (left/center/right/top/bottom pairs). */
        const std::string& head = parts[0];
        size_t at = head.find(" at ");
        std::string size_s = at == std::string::npos ? head : head.substr(0, at);
        std::string pos_s = at == std::string::npos ? std::string() : head.substr(at + 4);
        if (!pos_s.empty()) {
            std::vector<std::string> pp = split_space2(pos_s);
            auto pos1 = [&](const std::string& t, float base) -> float {
                if (t == "left" || t == "top") {
                    return 0.0f;
                }
                if (t == "center") {
                    return base * 0.5f;
                }
                if (t == "right" || t == "bottom") {
                    return base;
                }
                if (!t.empty() && t.back() == '%') {
                    return static_cast<float>(std::atof(t.c_str())) / 100.0f;
                }
                /* px: absolute, marked +100 like the legacy path */
                return static_cast<float>(std::atof(t.c_str())) + 100.0f;
            };
            if (pp.size() == 1) {
                if (pp[0] == "top" || pp[0] == "bottom") {
                    out.cy = pos1(pp[0], 1.0f);
                } else {
                    out.cx = pos1(pp[0], 1.0f);
                }
            } else if (pp.size() >= 2) {
                /* "left top" order still resolves (swap onto the axes) */
                bool p0v = pp[0] == "top" || pp[0] == "bottom";
                bool p1h = pp[1] == "left" || pp[1] == "right";
                if (p0v && p1h) {
                    out.cx = pos1(pp[1], 1.0f);
                    out.cy = pos1(pp[0], 1.0f);
                } else {
                    out.cx = pos1(pp[0], 1.0f);
                    out.cy = pos1(pp[1], 1.0f);
                }
            }
        }
        /* size keywords resolve at paint time (need the box); encode as
         * negative rx markers: -1 closest-side, -2 closest-corner,
         * -3 farthest-side, -4 farthest-corner (default). */
        float rx = 0, ry = 0;
        bool sized = false;
        if (std::sscanf(size_s.c_str(), "%fpx %fpx", &rx, &ry) == 2) {
            out.rx = rx;
            out.ry = ry;
            sized = true;
        } else if (size_s.find("circle") != std::string::npos) {
            const char* c = std::strchr(size_s.c_str(), ' ');
            if (c && std::atof(c) > 0) {
                out.rx = out.ry = static_cast<float>(std::atof(c));
            } else {
                out.rx = out.ry = -4.0f; /* circle farthest-corner */
            }
            sized = true;
        } else if (size_s.find("closest-side") != std::string::npos) {
            out.rx = out.ry = -1.0f;
            sized = true;
        } else if (size_s.find("closest-corner") != std::string::npos) {
            out.rx = out.ry = -2.0f;
            sized = true;
        } else if (size_s.find("farthest-side") != std::string::npos) {
            out.rx = out.ry = -3.0f;
            sized = true;
        } else if (size_s.find("farthest-corner") != std::string::npos) {
            out.rx = out.ry = -4.0f;
            sized = true;
        } else if (size_s.find("ellipse") != std::string::npos) {
            out.rx = out.ry = -4.0f;
            sized = true;
        }
        if (!sized) {
            out.rx = out.ry = -4.0f; /* default: farthest-corner */
        }
    } else {
        /* linear first part: "90deg" / "to right" */
        const std::string& head = parts[0];
        if (head.find("deg") != std::string::npos) {
            out.angle_deg = static_cast<float>(std::atof(head.c_str()));
        } else if (head == "to right") {
            out.angle_deg = 90.0f;
        } else if (head == "to left") {
            out.angle_deg = 270.0f;
        } else if (head == "to top") {
            out.angle_deg = 0.0f;
        } /* "to bottom" = default 180 */
    }
    /* a first part that parses as a colour is ALREADY a colour stop
     * ("linear-gradient(#f00, #00f)", "radial-gradient(#f00, #00f)"):
     * only a direction / size / position header is skipped. Skipping
     * parts[0] unconditionally left a single-stop gradient that painted
     * nothing at all - which read as "background-size is ignored" because
     * the probe that carried it was also a dir-less gradient. */
    unsigned int probe = 0;
    if (whaleui_render_parse_color(parts[0].c_str(), &probe) == 0) {
        first = 0;
    }
    /* stops: "color pos" / "color" */
    std::vector<size_t> auto_pos;
    for (size_t i = first; i < parts.size(); ++i) {
        const std::string& p = parts[i];
        size_t sp = std::string::npos;
        for (size_t j = 1; j < p.size(); ++j) {
            if (p[j] == ' ' && p[j - 1] != ' ') {
                sp = j;
                break;
            }
        }
        std::string col_s = sp == std::string::npos ? p : p.substr(0, sp);
        unsigned int c = 0;
        if (whaleui_render_parse_color(col_s.c_str(), &c) != 0) {
            continue;
        }
        GradStop st;
        st.c = c;
        st.pos = -1.0f;
        if (sp != std::string::npos) {
            std::string pos_s = p.substr(sp);
            const char* pc = pos_s.c_str();
            while (*pc == ' ' || *pc == '\t') {
                ++pc;
            }
            if (std::strchr(pc, '%')) {
                st.pos = static_cast<float>(std::atof(pc)) / 100.0f;
            } else {
                st.pos = static_cast<float>(std::atof(pc));
            }
        }
        out.stops.push_back(st);
        if (st.pos < 0) {
            auto_pos.push_back(out.stops.size() - 1);
        }
    }
    /* fill unspecified positions evenly */
    size_t n = out.stops.size();
    if (n == 0) {
        return 0;
    }
    if (auto_pos.empty()) {
        for (size_t i = 0; i < n; ++i) {
            out.stops[i].pos = n > 1 ? static_cast<float>(i) / static_cast<float>(n - 1) : 0.0f;
        }
    } else {
        for (size_t i = 0; i < auto_pos.size(); ++i) {
            size_t idx = auto_pos[i];
            float lo = idx == 0 ? 0.0f : out.stops[idx - 1].pos;
            float hi = (idx == 0 && n > 1) ? 1.0f
                                           : (idx + 1 < n ? out.stops[idx + 1].pos : 1.0f);
            if (idx > 0 && idx + 1 < n && out.stops[idx + 1].pos >= 0 &&
                out.stops[idx - 1].pos >= 0) {
                lo = out.stops[idx - 1].pos;
                hi = out.stops[idx + 1].pos;
            } else if (idx == 0) {
                lo = 0.0f;
            } else {
                hi = 1.0f;
            }
            out.stops[idx].pos = hi >= lo ? (lo + hi) / 2.0f : lo;
        }
    }
    return 1;
}

void radial_resolve(float rx, float ry, float rcx, float rcy, float x,
                    float y, float w, float h, float* orx, float* ory)
{
    float ox = rx, oy = ry;
    if (rx < 0 || ry < 0) {
        /* distances from the center to the box edges/corners */
        float dl = rcx - x, dr = x + w - rcx;
        float dt = rcy - y, db = y + h - rcy;
        if (dl < 0) {
            dl = 0;
        }
        if (dr < 0) {
            dr = 0;
        }
        if (dt < 0) {
            dt = 0;
        }
        if (db < 0) {
            db = 0;
        }
        int kind = static_cast<int>(rx < ry ? rx : ry);
        if (kind == -1) { /* closest-side */
            float m = dl;
            if (dr < m) {
                m = dr;
            }
            if (dt < m) {
                m = dt;
            }
            if (db < m) {
                m = db;
            }
            ox = oy = m;
        } else if (kind == -2) { /* closest-corner */
            float c1 = std::sqrt(dl * dl + dt * dt);
            float c2 = std::sqrt(dr * dr + dt * dt);
            float c3 = std::sqrt(dl * dl + db * db);
            float c4 = std::sqrt(dr * dr + db * db);
            float m = c1;
            if (c2 < m) {
                m = c2;
            }
            if (c3 < m) {
                m = c3;
            }
            if (c4 < m) {
                m = c4;
            }
            ox = oy = m;
        } else if (kind == -3) { /* farthest-side */
            float m = dl;
            if (dr > m) {
                m = dr;
            }
            if (dt > m) {
                m = dt;
            }
            if (db > m) {
                m = db;
            }
            ox = oy = m;
        } else { /* farthest-corner (default): ellipse radii */
            float ex = dl > dr ? dl : dr;
            float ey = dt > db ? dt : db;
            if (rx < 0 && ry < 0 && rx == ry) {
                /* circle: single radius to the farthest corner */
                float c1 = std::sqrt(dl * dl + dt * dt);
                float c2 = std::sqrt(dr * dr + dt * dt);
                float c3 = std::sqrt(dl * dl + db * db);
                float c4 = std::sqrt(dr * dr + db * db);
                float m = c1;
                if (c2 > m) {
                    m = c2;
                }
                if (c3 > m) {
                    m = c3;
                }
                if (c4 > m) {
                    m = c4;
                }
                ox = oy = m;
            } else {
                ox = ex;
                oy = ey;
            }
        }
    }
    if (ox <= 0) {
        ox = w * 0.5f;
    }
    if (oy <= 0) {
        oy = h * 0.5f;
    }
    if (orx) {
        *orx = ox;
    }
    if (ory) {
        *ory = oy;
    }
}

unsigned int grad_color(const Gradient& g, float t)
{
    size_t n = g.stops.size();
    if (n == 0) {
        return 0;
    }
    if (t <= 0.0f || t <= g.stops[0].pos) {
        return g.stops[0].c;
    }
    if (t >= g.stops[n - 1].pos) {
        return g.stops[n - 1].c;
    }
    for (size_t i = 0; i + 1 < n; ++i) {
        if (t <= g.stops[i + 1].pos) {
            float span = g.stops[i + 1].pos - g.stops[i].pos;
            float p = span > 0 ? (t - g.stops[i].pos) / span : 0.0f;
            unsigned int f = g.stops[i].c, g2 = g.stops[i + 1].c;
            auto ch = [p](unsigned int a, unsigned int b) -> unsigned int {
                return static_cast<unsigned int>(a + (static_cast<float>(b) - a) * p + 0.5f);
            };
            return (ch((f >> 24) & 0xFF, (g2 >> 24) & 0xFF) << 24) |
                   (ch((f >> 16) & 0xFF, (g2 >> 16) & 0xFF) << 16) |
                   (ch((f >> 8) & 0xFF, (g2 >> 8) & 0xFF) << 8) |
                   ch(f & 0xFF, g2 & 0xFF);
        }
    }
    return g.stops[n - 1].c;
}

/* 4x5 color matrix (row-major, input [r,g,b,a,1]): out[i] = m[i][0..3] *
 * in[0..3] + m[i][4]. Identity by default; filter ops left-multiply in
 * CSS order. */
void filter_matrix_identity(float m[4][5])
{
    for (int i = 0; i < 4; ++i) {
        for (int j = 0; j < 5; ++j) {
            m[i][j] = (i == j) ? 1.0f : 0.0f;
        }
    }
}

/* out = b * a (apply a first, then b) */
static void matrix_mul(const float b[4][5], const float a[4][5],
                       float out[4][5])
{
    float t[4][5];
    for (int i = 0; i < 4; ++i) {
        for (int j = 0; j < 4; ++j) {
            t[i][j] = b[i][0] * a[0][j] + b[i][1] * a[1][j] +
                      b[i][2] * a[2][j] + b[i][3] * a[3][j];
        }
        t[i][4] = b[i][0] * a[0][4] + b[i][1] * a[1][4] +
                  b[i][2] * a[2][4] + b[i][3] * a[3][4] + b[i][4];
    }
    for (int i = 0; i < 4; ++i) {
        for (int j = 0; j < 5; ++j) {
            out[i][j] = t[i][j];
        }
    }
}

static float filter_num(const char* s, size_t n)
{
    std::string t(s, n);
    size_t b = t.find_first_not_of(" \t");
    size_t e = t.find_last_not_of(" \t");
    if (b == std::string::npos) {
        return 1.0f;
    }
    t = t.substr(b, e - b + 1);
    float v = static_cast<float>(std::atof(t.c_str()));
    if (!t.empty() && t.back() == '%') {
        v /= 100.0f;
    }
    return v;
}

/* Parse `filter` into a 4x5 color matrix + blur radius. Supported ops
 * (applied left to right): blur(Npx), brightness(N), contrast(N),
 * saturate(N), grayscale(N) (= saturate(1-N)), invert(N), sepia(N),
 * hue-rotate(Ndeg), opacity(N). Unknown ops are skipped (the rest still
 * applies). Returns 0 when at least one op parsed (even a no-op one). */
int parse_filter(const char* v, float m[4][5], float* blur)
{
    if (blur) {
        *blur = 0;
    }
    if (!v || !m) {
        return -1;
    }
    filter_matrix_identity(m);
    bool any = false;
    const char* p = v;
    while (*p) {
        while (*p == ' ' || *p == '\t' || *p == ',') {
            ++p;
        }
        if (!*p) {
            break;
        }
        const char* fn = p;
        while (*p && *p != '(' && *p != ' ' && *p != '\t') {
            ++p;
        }
        std::string name(fn, static_cast<size_t>(p - fn));
        while (*p == ' ' || *p == '\t') {
            ++p;
        }
        if (*p != '(') {
            continue; /* bare keyword (e.g. "none"): stop */
        }
        ++p;
        const char* as = p;
        int depth = 1;
        while (*p && depth > 0) {
            if (*p == '(') {
                ++depth;
            } else if (*p == ')') {
                --depth;
            }
            if (depth > 0) {
                ++p;
            }
        }
        std::string arg(as, static_cast<size_t>(p - as));
        if (*p == ')') {
            ++p;
        }
        float op[4][5];
        filter_matrix_identity(op);
        bool ok = true;
        if (name == "blur") {
            float b = filter_num(arg.c_str(), arg.size());
            if (arg.find("px") == std::string::npos &&
                arg.find_first_of("0123456789") == std::string::npos) {
                b = 0;
            }
            if (blur && b > *blur) {
                *blur = b;
            }
            any = true;
            continue; /* blur is a radius, not a color op */
        } else if (name == "brightness") {
            float b = filter_num(arg.c_str(), arg.size());
            op[0][0] = op[1][1] = op[2][2] = b;
        } else if (name == "contrast") {
            float c = filter_num(arg.c_str(), arg.size());
            op[0][0] = op[1][1] = op[2][2] = c;
            op[0][4] = op[1][4] = op[2][4] = (1.0f - c) * 0.5f;
        } else if (name == "saturate") {
            float s = filter_num(arg.c_str(), arg.size());
            float l0 = 0.2126f, l1 = 0.7152f, l2 = 0.0722f;
            op[0][0] = l0 + (1 - l0) * s;
            op[0][1] = l1 - l1 * s;
            op[0][2] = l2 - l2 * s;
            op[1][0] = l0 - l0 * s;
            op[1][1] = l1 + (1 - l1) * s;
            op[1][2] = l2 - l2 * s;
            op[2][0] = l0 - l0 * s;
            op[2][1] = l1 - l1 * s;
            op[2][2] = l2 + (1 - l2) * s;
        } else if (name == "grayscale") {
            float g = filter_num(arg.c_str(), arg.size());
            float s = 1.0f - g;
            float l0 = 0.2126f, l1 = 0.7152f, l2 = 0.0722f;
            op[0][0] = l0 + (1 - l0) * s;
            op[0][1] = l1 - l1 * s;
            op[0][2] = l2 - l2 * s;
            op[1][0] = l0 - l0 * s;
            op[1][1] = l1 + (1 - l1) * s;
            op[1][2] = l2 - l2 * s;
            op[2][0] = l0 - l0 * s;
            op[2][1] = l1 - l1 * s;
            op[2][2] = l2 + (1 - l2) * s;
        } else if (name == "invert") {
            float n = filter_num(arg.c_str(), arg.size());
            op[0][0] = op[1][1] = op[2][2] = 1.0f - 2.0f * n;
            op[0][4] = op[1][4] = op[2][4] = n;
        } else if (name == "sepia") {
            float n = filter_num(arg.c_str(), arg.size());
            float sm[3][3] = {{0.393f, 0.769f, 0.189f},
                              {0.349f, 0.686f, 0.168f},
                              {0.272f, 0.534f, 0.131f}};
            for (int i = 0; i < 3; ++i) {
                for (int j = 0; j < 3; ++j) {
                    op[i][j] = (i == j ? (1.0f - n) : 0.0f) + n * sm[i][j];
                }
            }
        } else if (name == "hue-rotate") {
            float deg = static_cast<float>(std::atof(arg.c_str()));
            float rad = deg * 3.14159265f / 180.0f;
            float cs = std::cos(rad), sn = std::sin(rad);
            /* CSS hue-rotate matrix (luma-axis rotation) */
            op[0][0] = 0.2126f + cs * 0.7874f - sn * 0.2126f;
            op[0][1] = 0.7152f - cs * 0.7152f - sn * 0.7152f;
            op[0][2] = 0.0722f - cs * 0.0722f + sn * 0.9278f;
            op[1][0] = 0.2126f - cs * 0.2126f + sn * 0.1430f;
            op[1][1] = 0.7152f + cs * 0.2848f + sn * 0.1400f;
            op[1][2] = 0.0722f - cs * 0.0722f - sn * 0.2830f;
            op[2][0] = 0.2126f - cs * 0.2126f - sn * 0.7874f;
            op[2][1] = 0.7152f - cs * 0.7152f + sn * 0.7152f;
            op[2][2] = 0.0722f + cs * 0.9278f + sn * 0.0722f;
        } else if (name == "opacity") {
            float o = filter_num(arg.c_str(), arg.size());
            op[3][3] = o;
        } else {
            ok = false;
        }
        if (ok) {
            float merged[4][5];
            matrix_mul(op, m, merged);
            for (int i = 0; i < 4; ++i) {
                for (int j = 0; j < 5; ++j) {
                    m[i][j] = merged[i][j];
                }
            }
            any = true;
        }
    }
    return any ? 0 : -1;
}

void fill_gradient(std::vector<unsigned int>& fb, int fbw, int fbh,
                   int x, int y, int w, int h, const Gradient& g,
                   const Clip* clip, float rot_deg, float skx_deg,
                   float sky_deg)
{
    if (g_gpu) {
        /* linear gradients: corner colors (projected onto the gradient
         * axis) interpolated by the solid pipeline - free from the
         * rasterizer. Stops beyond the first two approximate with the
         * first/last color (ponytail: per-stop segments when a page needs
         * them). Radial needs per-pixel work the graphics pipeline cannot
         * do (SDL 3.4 D3D12 graphics SRV is broken), so it is skipped -
         * the flat element background underneath stays correct. */
        if (g.type == 0 && g.stops.size() >= 2) {
            float rad = g.angle_deg * 3.14159265f / 180.0f;
            float ddx = std::sin(rad), ddy = -std::cos(rad);
            /* a transformed element's gradient axis follows it (CSS):
             * shear the projection direction by the box's skew, then
             * rotate by its rot; the band positions come from the same
             * box-corner projections, so the whole gradient turns with
             * the background for a few ALU ops - no extra texture/draw */
            if (skx_deg != 0.0f || sky_deg != 0.0f) {
                float tx = 0, ty = 0;
                if (skx_deg != 0.0f) {
                    tx = std::tan(skx_deg * 3.14159265f / 180.0f);
                }
                if (sky_deg != 0.0f) {
                    ty = std::tan(sky_deg * 3.14159265f / 180.0f);
                }
                /* inverse-transpose the direction (covariant under shear):
                 * d' = (ddx - ty*ddy, ddy - tx*ddx) normalized below by
                 * the span computation */
                float nx = ddx - ty * ddy;
                float ny = ddy - tx * ddx;
                ddx = nx;
                ddy = ny;
            }
            if (rot_deg != 0.0f) {
                float rr = rot_deg * 3.14159265f / 180.0f;
                float cs = std::cos(rr), sn = std::sin(rr);
                float nx = ddx * cs - ddy * sn;
                float ny = ddx * sn + ddy * cs;
                ddx = nx;
                ddy = ny;
            }
            float ccx = x + w * 0.5f, ccy = y + h * 0.5f;
            float t0 = 1e30f, t1 = -1e30f;
            const float corners[4][2] = {
                {static_cast<float>(x), static_cast<float>(y)},
                {static_cast<float>(x + w), static_cast<float>(y)},
                {static_cast<float>(x), static_cast<float>(y + h)},
                {static_cast<float>(x + w), static_cast<float>(y + h)}};
            for (int i = 0; i < 4; ++i) {
                float t = (corners[i][0] - ccx) * ddx +
                          (corners[i][1] - ccy) * ddy;
                if (t < t0) {
                    t0 = t;
                }
                if (t > t1) {
                    t1 = t;
                }
            }
            float span = t1 - t0;
            if (span <= 0.0f) {
                span = 1.0f;
            }
            auto tcol = [&](float px, float py) {
                float t = ((px - ccx) * ddx + (py - ccy) * ddy - t0) / span;
                return grad_color(g, t);
            };
            unsigned int c_tl = tcol(static_cast<float>(x), static_cast<float>(y));
            unsigned int c_tr = tcol(static_cast<float>(x + w), static_cast<float>(y));
            unsigned int c_bl = tcol(static_cast<float>(x), static_cast<float>(y + h));
            unsigned int c_br = tcol(static_cast<float>(x + w), static_cast<float>(y + h));
            int c2[4];
            const int* cp = nullptr;
            if (clip) {
                c2[0] = clip->x;
                c2[1] = clip->y;
                c2[2] = clip->w;
                c2[3] = clip->h;
                cp = c2;
            }
            whaleui_gpu_gradient_rect(g_gpu, static_cast<float>(x),
                                      static_cast<float>(y),
                                      static_cast<float>(w),
                                      static_cast<float>(h), c_tl, c_tr, c_bl,
                                      c_br, cp);
        } else if (g.type == 1 && g.stops.size() >= 2) {
            /* radial: concentric rounded-rect ellipses, alpha fading
             * outwards - a coarse approximation of the per-pixel ellipse
             * distance (10 layers, GPU-trivial) */
            float rcx = g.cx > 1.0f ? g.cx - 100.0f : x + g.cx * w;
            float rcy = g.cy > 1.0f ? g.cy - 100.0f : y + g.cy * h;
            float rx = 0, ry = 0;
            radial_resolve(g.rx, g.ry, rcx, rcy, static_cast<float>(x),
                           static_cast<float>(y), static_cast<float>(w),
                           static_cast<float>(h), &rx, &ry);
            int c2[4];
            const int* cp = nullptr;
            if (clip) {
                c2[0] = clip->x;
                c2[1] = clip->y;
                c2[2] = clip->w;
                c2[3] = clip->h;
                cp = c2;
            }
            const int kLayers = 10;
            for (int i = kLayers; i >= 1; --i) {
                float t = static_cast<float>(i) / kLayers;
                unsigned int c = grad_color(g, t);
                if (((c >> 24) & 0xFF) == 0) {
                    continue;
                }
                float sx = rcx - rx * t;
                float sy = rcy - ry * t;
                whaleui_gpu_rect(g_gpu, sx, sy, rx * 2.0f * t,
                                 ry * 2.0f * t, rx * t, c, cp);
            }
        }
        return;
    }
    if (w <= 0 || h <= 0 || g.stops.empty()) {
        return;
    }
    int x0 = x < 0 ? 0 : x;
    int y0 = y < 0 ? 0 : y;
    int x1 = x + w > fbw ? fbw : x + w;
    int y1 = y + h > fbh ? fbh : y + h;
    clip_rect(x0, y0, x1, y1, clip);
    if (x1 <= x0 || y1 <= y0) {
        return;
    }
    auto blend = [&](int px, int py, unsigned int c) {
        unsigned int a = (c >> 24) & 0xFF;
        if (a == 0) {
            return;
        }
        unsigned int& d = fb[static_cast<size_t>(py) * fbw + px];
        if (a == 255) {
            d = 0xFF000000 | (c & 0x00FFFFFF);
            return;
        }
        unsigned int cr = (c >> 16) & 0xFF, cg = (c >> 8) & 0xFF, cb = c & 0xFF;
        unsigned int dr = (d >> 16) & 0xFF, dg = (d >> 8) & 0xFF, db = d & 0xFF;
        d = 0xFF000000 |
            (((cr * a + dr * (255 - a)) / 255) << 16) |
            (((cg * a + dg * (255 - a)) / 255) << 8) |
            ((cb * a + db * (255 - a)) / 255);
    };
    if (g.type == 0) {
        /* linear: project pixels onto the direction axis */
        float rad = g.angle_deg * 3.14159265f / 180.0f;
        float dx = std::sin(rad), dy = -std::cos(rad);
        float cx = x + w * 0.5f, cy = y + h * 0.5f;
        float t0 = 1e30f, t1 = -1e30f;
        const float corners[4][2] = {
            {static_cast<float>(x), static_cast<float>(y)},
            {static_cast<float>(x + w), static_cast<float>(y)},
            {static_cast<float>(x), static_cast<float>(y + h)},
            {static_cast<float>(x + w), static_cast<float>(y + h)}};
        for (int i = 0; i < 4; ++i) {
            float t = (corners[i][0] - cx) * dx + (corners[i][1] - cy) * dy;
            if (t < t0) {
                t0 = t;
            }
            if (t > t1) {
                t1 = t;
            }
        }
        float span = t1 - t0;
        if (span <= 0.0f) {
            span = 1.0f;
        }
        for (int py = y0; py < y1; ++py) {
            float t = ((static_cast<float>(x0) - cx) * dx +
                       (static_cast<float>(py) - cy) * dy - t0) /
                      span;
            float step = dx / span;
            for (int px = x0; px < x1; ++px) {
                blend(px, py, grad_color(g, t));
                t += step;
            }
        }
    } else {
        /* radial: ellipse distance from the center */
        float rcx = g.cx > 1.0f ? g.cx - 100.0f : x + g.cx * w;
        float rcy = g.cy > 1.0f ? g.cy - 100.0f : y + g.cy * h;
        float rx = 0, ry = 0;
        radial_resolve(g.rx, g.ry, rcx, rcy, static_cast<float>(x),
                       static_cast<float>(y), static_cast<float>(w),
                       static_cast<float>(h), &rx, &ry);
        if (rx <= 0 || ry <= 0) {
            return;
        }
        for (int py = y0; py < y1; ++py) {
            float ny = (static_cast<float>(py) - rcy) / ry;
            for (int px = x0; px < x1; ++px) {
                float nx = (static_cast<float>(px) - rcx) / rx;
                float t = std::sqrt(nx * nx + ny * ny);
                blend(px, py, grad_color(g, t));
            }
        }
    }
}

extern "C" int whaleui_render_parse_color(const char* s, unsigned int* out)
{
    if (!s || !out) {
        return -1;
    }
    while (*s == ' ' || *s == '\t') {
        ++s;
    }
    if (*s == '#') {
        ++s;
        int ok = 1;
        size_t n = std::strlen(s);
        if (n == 3) { /* #rgb */
            int ok = 1;
            unsigned int r = hex_nib(s[0], &ok);
            unsigned int g = hex_nib(s[1], &ok);
            unsigned int b = hex_nib(s[2], &ok);
            *out = 0xFF000000 | ((r * 0x11) << 16) | ((g * 0x11) << 8) | (b * 0x11);
            return ok ? 0 : -2;
        }
        if (n == 6 || n == 8) {
            unsigned int r = hex_byte(s, &ok);
            unsigned int g = hex_byte(s + 2, &ok);
            unsigned int b = hex_byte(s + 4, &ok);
            unsigned int a = n == 8 ? hex_byte(s + 6, &ok) : 0xFF;
            *out = (a << 24) | (r << 16) | (g << 8) | b;
            return ok ? 0 : -2;
        }
        return -3;
    }
    if (std::strncmp(s, "rgba(", 5) == 0 || std::strncmp(s, "rgb(", 4) == 0) {
        int rr = 0, gg = 0, bb = 0;
        float faf = -1.0f;
        if (std::sscanf(s, "rgba( %d , %d , %d , %f )", &rr, &gg, &bb, &faf) >= 4) {
            unsigned int r = rr < 0 ? 0 : static_cast<unsigned>(rr);
            unsigned int g = gg < 0 ? 0 : static_cast<unsigned>(gg);
            unsigned int b = bb < 0 ? 0 : static_cast<unsigned>(bb);
            /* alpha: 0..1 float, or legacy 0..255 integer */
            unsigned int a = faf <= 1.0f
                                 ? static_cast<unsigned>(faf * 255.0f + 0.5f)
                                 : static_cast<unsigned>(faf);
            if (r > 255) { r = 255; }
            if (g > 255) { g = 255; }
            if (b > 255) { b = 255; }
            if (a > 255) { a = 255; }
            *out = (a << 24) | (r << 16) | (g << 8) | b;
            return 0;
        }
        if (std::sscanf(s, "rgb( %d , %d , %d )", &rr, &gg, &bb) >= 3) {
            unsigned int r = rr < 0 ? 0 : static_cast<unsigned>(rr);
            unsigned int g = gg < 0 ? 0 : static_cast<unsigned>(gg);
            unsigned int b = bb < 0 ? 0 : static_cast<unsigned>(bb);
            if (r > 255) { r = 255; }
            if (g > 255) { g = 255; }
            if (b > 255) { b = 255; }
            *out = (255 << 24) | (r << 16) | (g << 8) | b;
            return 0;
        }
        return -4;
    }
    if (std::strncmp(s, "hsl(", 4) == 0 || std::strncmp(s, "hsla(", 5) == 0) {
        /* hsl()/hsla(): H in degrees (deg/grad/rad/turn accepted), S/L in %.
         * 80%-bucket function that pages reach for constantly; without it
         * the declaration fell through to "not a colour" and painted the
         * default. */
        float h = 0, sat = 0, li = 0, faf = -1.0f;
        int n = 0;
        /* the format spaces make sscanf tolerate "hsl(210, 50%, 40%)" as
         * well as the compact form */
        if (std::strncmp(s, "hsla(", 5) == 0) {
            n = std::sscanf(s, "hsla( %f , %f %% , %f %% , %f )", &h, &sat, &li,
                            &faf);
        } else {
            n = std::sscanf(s, "hsl( %f , %f %% , %f %% )", &h, &sat, &li);
            if (n == 3) {
                faf = 1.0f;
            }
        }
        if (n >= 3) {
            /* H unit: deg (default) / grad / rad / turn - checked in that
             * order because "grad" contains "rad" */
            if (std::strstr(s, "turn")) {
                h *= 360.0f;
            } else if (std::strstr(s, "grad")) {
                h = h * 0.9f;
            } else if (std::strstr(s, "rad")) {
                h = h * 180.0f / 3.14159265f;
            }
            h = std::fmod(h, 360.0f);
            if (h < 0) {
                h += 360.0f;
            }
            if (sat < 0) { sat = 0; }
            if (sat > 100) { sat = 100; }
            if (li < 0) { li = 0; }
            if (li > 100) { li = 100; }
            const float sf = sat / 100.0f, lf = li / 100.0f;
            const float c = (1.0f - std::fabs(2.0f * lf - 1.0f)) * sf;
            const float hp = h / 60.0f;
            const float x = c * (1.0f - std::fabs(std::fmod(hp, 2.0f) - 1.0f));
            float r = 0, g = 0, b = 0;
            if (hp < 1) { r = c; g = x; }
            else if (hp < 2) { r = x; g = c; }
            else if (hp < 3) { g = c; b = x; }
            else if (hp < 4) { g = x; b = c; }
            else if (hp < 5) { r = x; b = c; }
            else { r = c; b = x; }
            const float m = lf - c / 2.0f;
            unsigned int rr = static_cast<unsigned>((r + m) * 255.0f + 0.5f);
            unsigned int gg = static_cast<unsigned>((g + m) * 255.0f + 0.5f);
            unsigned int bb = static_cast<unsigned>((b + m) * 255.0f + 0.5f);
            if (faf < 0) { faf = 1.0f; }
            unsigned int a = faf <= 1.0f
                                 ? static_cast<unsigned>(faf * 255.0f + 0.5f)
                                 : static_cast<unsigned>(faf);
            if (rr > 255) { rr = 255; }
            if (gg > 255) { gg = 255; }
            if (bb > 255) { bb = 255; }
            if (a > 255) { a = 255; }
            *out = (a << 24) | (rr << 16) | (gg << 8) | bb;
            return 0;
        }
        return -5;
    }
    for (const NamedColor& nc : k_named) {
        if (std::strcmp(s, nc.name) == 0) {
            *out = nc.value;
            return 0;
        }
    }
    return -5;
}

unsigned int color_of(const WhaleUIComputedStyle& s, const char* prop, unsigned int def)
{
    std::string v = sget(s, prop);
    if (v.empty()) {
        return def;
    }
    unsigned int c = 0;
    if (whaleui_render_parse_color(v.c_str(), &c) == 0) {
        return c;
    }
    return def;
}

unsigned int border_color_of(const WhaleUIComputedStyle& s, unsigned int def)
{
    std::string v = sget(s, "border");
    if (v.empty()) {
        return def;
    }
    unsigned int c = 0;
    if (whaleui_render_parse_color(v.c_str(), &c) == 0) {
        return c;
    }
    const char* p = v.c_str();
    while (*p) {
        while (*p == ' ' || *p == '\t') {
            ++p;
        }
        const char* s = p;
        while (*s && *s != ' ' && *s != '\t' && *s != ';') {
            ++s;
        }
        std::string tok(p, static_cast<size_t>(s - p));
        if (whaleui_render_parse_color(tok.c_str(), &c) == 0) {
            return c;
        }
        p = s;
    }
    return def;
}

/* Color of ONE border side (0=top 1=right 2=bottom 3=left). Resolution
 * order matches CSS: the border-<side>-color longhand, then the
 * "border-color" TRBL shorthand (1 value = all, 2 = tb/lr, 3 = t/lr/b,
 * 4 = t/r/b/l), then the color inside the "border" shorthand. Themes
 * (aero's bevel inputs, photon's buttons) set four different sides and
 * the single-color path flattened them to one. */
unsigned int border_side_color(const WhaleUIComputedStyle& s, int side,
                               unsigned int def)
{
    static const char* kSide[4] = {"border-top-color", "border-right-color",
                                   "border-bottom-color", "border-left-color"};
    unsigned int c = 0;
    std::string lh = sget(s, kSide[side]);
    if (!lh.empty() && whaleui_render_parse_color(lh.c_str(), &c) == 0) {
        return c;
    }
    std::string v = sget(s, "border-color");
    if (!v.empty()) {
        std::vector<std::string> tok;
        const char* p = v.c_str();
        while (*p) {
            while (*p == ' ' || *p == '\t') {
                ++p;
            }
            if (!*p) {
                break;
            }
            const char* b = p;
            while (*p && *p != ' ' && *p != '\t') {
                ++p;
            }
            tok.emplace_back(b, static_cast<size_t>(p - b));
        }
        size_t n = tok.size();
        const std::string* pick = nullptr;
        if (n == 1) {
            pick = &tok[0];
        } else if (n == 2) {
            pick = &tok[side == 1 || side == 3 ? 1 : 0];
        } else if (n == 3) {
            pick = &tok[side == 0 ? 0 : (side == 2 ? 2 : 1)];
        } else if (n >= 4) {
            pick = &tok[static_cast<size_t>(side)];
        }
        if (pick && whaleui_render_parse_color(pick->c_str(), &c) == 0) {
            return c;
        }
    }
    return border_color_of(s, def);
}
